[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "flexible-work-policy-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "flexible-work-policy-surface",
      "components": [
        {
          "id": "root",
          "type": "Card",
          "properties": {
            "title": "Flexible Work Policy Summary",
            "children": [
              "policy_list"
            ]
          }
        },
        {
          "id": "policy_list",
          "type": "List",
          "properties": {
            "children": [
              "remote_work_item",
              "core_hours_item",
              "requests_item",
              "stipend_item",
              "office_visit_item"
            ]
          }
        },
        {
          "id": "remote_work_item",
          "type": "ListItem",
          "properties": {
            "primaryText": "Remote Work",
            "secondaryText": "Employees may work remotely up to three days per week.",
            "leadingComponentId": "remote_icon"
          }
        },
        {
          "id": "remote_icon",
          "type": "Icon",
          "properties": {
            "icon": "home"
          }
        },
        {
          "id": "core_hours_item",
          "type": "ListItem",
          "properties": {
            "primaryText": "Core Hours",
            "secondaryText": "All staff must be available from 10:00 AM to 3:00 PM EST.",
            "leadingComponentId": "hours_icon"
          }
        },
        {
          "id": "hours_icon",
          "type": "Icon",
          "properties": {
            "icon": "schedule"
          }
        },
        {
          "id": "requests_item",
          "type": "ListItem",
          "properties": {
            "primaryText": "Remote Day Requests",
            "secondaryText": "Submit requests via the HR portal by Friday of the prior week.",
            "leadingComponentId": "request_icon"
          }
        },
        {
          "id": "request_icon",
          "type": "Icon",
          "properties": {
            "icon": "edit_calendar"
          }
        },
        {
          "id": "stipend_item",
          "type": "ListItem",
          "properties": {
            "primaryText": "Equipment Stipend",
            "secondaryText": "An annual stipend of $500 is provided for remote setups.",
            "leadingComponentId": "stipend_icon"
          }
        },
        {
          "id": "stipend_icon",
          "type": "Icon",
          "properties": {
            "icon": "payments"
          }
        },
        {
          "id": "office_visit_item",
          "type": "ListItem",
          "properties": {
            "primaryText": "Quarterly Office Visit",
            "secondaryText": "All employees must travel to the New York office once per quarter.",
            "leadingComponentId": "visit_icon"
          }
        },
        {
          "id": "visit_icon",
          "type": "Icon",
          "properties": {
            "icon": "groups"
          }
        }
      ]
    }
  }
]
